onMounted(() => {
  const ac = new AbortController()
  void (async () => {
    try {
      user.value = await api.getUser(props.id, { signal: ac.signal })
    } catch (e) {
      if ((e as { name?: string }).name === 'AbortError') return
      error.value = e
    }
  })()
  onBeforeUnmount(() => ac.abort())
})

